//! The sample library (generated by tools/gen-samplelib.py), embedded in
//! the plugin. Faust reads noise loops through `sl_loop` and the sample
//! layers' hits through `sl_hit` (see lib.rs).

include!("samplelib_index.rs");

static DATA: &[u8] = include_bytes!("samplelib.bin");

#[inline(always)]
fn frame(i: usize) -> f32 {
    i16::from_le_bytes([DATA[2 * i], DATA[2 * i + 1]]) as f32 / 32768.0
}

/// Loop `k` at position `pos` in samples, wrapped so it repeats seamlessly,
/// with linear interpolation; silent for an unknown loop.
#[inline(always)]
pub fn read_loop(k: i32, pos: f32) -> f32 {
    let Some(&len) = usize::try_from(k).ok().and_then(|k| LOOP_LENS.get(k)) else {
        return 0.0;
    };
    if !pos.is_finite() || len == 0 {
        return 0.0;
    }
    let p = pos.rem_euclid(len as f32);
    let i = (p as usize).min(len as usize - 1);
    let frac = p - i as f32;
    let start = LOOP_STARTS[k as usize] as usize;
    let (a, b) = (frame(start + i), frame(start + (i + 1) % len as usize));
    a + (b - a) * frac
}

/// Hit `k` at position `pos` in samples, linearly interpolated; silent for
/// an unknown hit or a position outside it.
#[inline(always)]
pub fn read_hit(k: i32, pos: f32) -> f32 {
    let Some(&len) = usize::try_from(k).ok().and_then(|k| HIT_LENS.get(k)) else {
        return 0.0;
    };
    if pos.is_nan() || pos < 0.0 || pos >= (len - 1) as f32 {
        return 0.0;
    }
    let start = HIT_STARTS[k as usize] as usize;
    let i = pos as usize;
    let frac = pos - i as f32;
    let (a, b) = (frame(start + i), frame(start + i + 1));
    a + (b - a) * frac
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn library_is_present_and_sane() {
        let total: u32 = LOOP_LENS.iter().chain(HIT_LENS.iter()).sum();
        assert_eq!(DATA.len(), total as usize * 2);
        for k in 0..LOOP_LENS.len() as i32 {
            let len = LOOP_LENS[k as usize] as f32;
            let peak = (0..LOOP_LENS[k as usize]).map(|i| read_loop(k, i as f32).abs()).fold(0.0, f32::max);
            assert!(peak > 0.01 && peak <= 1.0, "loop {k} peak {peak}");
            // Wrapping: one loop length later reads the same sample.
            assert!((read_loop(k, 10.0) - read_loop(k, 10.0 + len)).abs() < 1e-3);
        }
        assert_eq!(read_loop(-1, 0.0), 0.0);
        assert_eq!(read_loop(LOOP_LENS.len() as i32, 0.0), 0.0);
        assert_eq!(read_loop(0, f32::NAN), 0.0);
        // Hits: peak-normalized to about -1 dBFS, silent outside.
        for k in 0..HIT_LENS.len() as i32 {
            let peak = (0..HIT_LENS[k as usize] - 1).map(|i| read_hit(k, i as f32).abs()).fold(0.0, f32::max);
            assert!(peak > 0.8 && peak <= 1.0, "hit {k} peak {peak}");
        }
        assert_eq!(read_hit(0, -1.0), 0.0);
        assert_eq!(read_hit(0, 1e9), 0.0);
        assert_eq!(read_hit(HIT_LENS.len() as i32, 0.0), 0.0);
        assert_eq!(HIT_NAMES.len(), HIT_LENS.len());
    }
}
